import { Component } from "@angular/core";
import { FormControl, ReactiveFormsModule, Validators } from "@angular/forms";
@Component({
  selector: "app-livre-form", standalone: true, imports: [ReactiveFormsModule],
  template: `<label for="titre">Titre</label><input id="titre" [formControl]="titre">
    <p>{{ titre.invalid ? "Titre requis ou trop long" : "Prêt" }}</p>`
})
export class LivreForm {
  readonly titre = new FormControl("", { nonNullable: true, validators: [Validators.required, Validators.maxLength(80)] });
}

const controle = new FormControl("", { nonNullable: true, validators: [Validators.required, Validators.maxLength(80)] });
controle.setValue("Web");
console.log(controle.valid); // true
